"""Generate finite proof terms for Agda to verify the two-wire decoder."""
from pathlib import Path

HERE = Path(__file__).resolve().parent


def fin(n):
    return "(" + "suc (" * n + "zero" + ")" * n + ")"


def absurd(n):
    return "(" + "s≤s (" * n + ")" + ")" * n


body = """------------------------------------------------------------------------
-- Presentations of groups
--
-- Exact two-wire decoder identities, generated by build_checks.py.
------------------------------------------------------------------------

{-# OPTIONS --without-K --safe #-}

module Examples.Groups.CCX+H.TwoQubit.Checks where

open import Data.Fin.Base using (Fin ; zero ; suc ; _<_)
open import Data.Nat.Base using (s≤s ; z≤n)
open import Relation.Binary.PropositionalEquality using (_≡_ ; refl)
open import Word.Base using ([_]ʷ)
open import Examples.Groups.CCX+H.Encoding using (encode)
open import Examples.Groups.CCX+H.TwoQubit.Decoding
import Examples.Groups.CCX+HH-TwoLevel.Syntactics as U
import Examples.Groups.CCX+HH-TwoLevel.Scaled.Syntactics as T
import Examples.Groups.CCX+HH-TwoLevel.Scaled.Semantics as S
import Examples.Groups.Real-Clifford+CH-TwoLevel.Ring as R

private module M = S.Dim 2

opaque
  unfolding S.actV S.set₁ S.set₂ R._+ᴰ_ R._*ᴰ_ R.-ᴰ_

  sign-correct : ∀ a → M.⟦ encode (sign a) ⟧ᴸ ≡ M.⟦ [ T.⌊ U.M-gen a ⌋ ]ʷ ⟧ᴸ
"""
for a in range(4):
    body += f"  sign-correct {fin(a)} = refl\n"
body += "\n  exchange-correct : ∀ a b (p : a < b) → M.⟦ encode (exchange a b) ⟧ᴸ ≡ M.⟦ [ T.⌊ U.X-gen a b p ⌋ ]ʷ ⟧ᴸ\n"
for a in range(4):
    for b in range(4):
        body += (f"  exchange-correct {fin(a)} {fin(b)} p = refl\n" if a < b
                 else f"  exchange-correct {fin(a)} {fin(b)} {absurd(b)}\n")
body += "\n  k-correct : ∀ a b c d (p : a < b) (q : b < c) (r : c < d) → M.⟦ encode HH ⟧ᴸ ≡ M.⟦ [ T.⌊ U.K-gen a b c d p q r ⌋ ]ʷ ⟧ᴸ\n"
for a in range(4):
    for b in range(4):
        if a >= b:
            body += f"  k-correct {fin(a)} {fin(b)} c d {absurd(b)} q r\n"
            continue
        for c in range(4):
            if b >= c:
                body += f"  k-correct {fin(a)} {fin(b)} {fin(c)} d p {absurd(c)} r\n"
                continue
            for d in range(4):
                body += (f"  k-correct {fin(a)} {fin(b)} {fin(c)} {fin(d)} p q r = refl\n"
                         if c < d else f"  k-correct {fin(a)} {fin(b)} {fin(c)} {fin(d)} p q {absurd(d)}\n")
(HERE / "Checks.agda").write_text(body, encoding="utf-8")
